fn rolling_max(s: &Vec<i8>) -> Option<i8> {
    // If there are fewer than two elements, we can't have a "second-largest"
    if s.len() < 2 {
        return None;
    }

    // Track the largest and second-largest values seen so far.
    // Initialize both to the minimum possible i8.
    let mut max1 = i8::MIN;
    let mut max2 = i8::MIN;

    for &val in s {
        if val > max1 {
            // New maximum found: demote the old max1 to max2
            max2 = max1;
            max1 = val;
        } else if val > max2 {
            // val is not bigger than max1 but is bigger than max2
            max2 = val;
        }
    }

    Some(max2)
}

